function governance_admin(app, pageViewModel, templatePath, contextList) {
    app.get('#/governance/administration', function (context) {
        context.app.swap('');
        context.title(pageViewModel.Title);

        var type = 'ResponsibilityType';

        pageViewModel.breadcrumbs = [];
        pageViewModel.breadcrumbs.push({ Name: 'Administration' });
        pageViewModel.breadcrumbs.push({ Name: 'Type Management' });
        pageViewModel.breadcrumbs.push({ Name: pageViewModel.Title, Active: true });
        var permissions = new PermissionsModel();

        var GovernanceAdapter;
        var GovernanceSource;

        //#region Event Handlers

        function adminResponsibilityTypeGridBindingComplete(event) {
            var displayCount = $('#AdminResponsibilityTypeGrid').jqxGrid('getdisplayrows').length;
            if (displayCount > 0) {
                $('#AdminResponsibilityTypeGrid').jqxGrid('selectrow', 0);
            }
        }

        function adminResponsibilityTypeGridRowSelect(event) {
            var args = event.args;
            var data = args.row;

            amplify.publish(AmplifyActions.TileUnsubscribe, {});
            $('#SideIcons').PageTools("reload", type, data.ID);

            DetailTile('DetailTile', contextList, permissions, type, data.ID);
            //$('#UsageTile').load('/parts/ResponsibilityTypeUsageGrid?id=' + data.ID);
        }

        function saveAction(data) {
            try {
                switch (data.context) {
                    case contextList.ResponsibilityType:
                        DetailTile('DetailTile', contextList, permissions, type, data.id);
                        $('#AdminResponsibilityTypeGrid').jqxGrid('updatebounddata');
                        break;
                }
            } catch (e) { }
        }

        function unsubscribe(data) {
            GovernanceAdapter = null;
            GovernanceSource = null;

            $("#AdminResponsibilityTypeGrid").off("bindingcomplete", adminResponsibilityTypeGridBindingComplete);
            $("#AdminResponsibilityTypeGrid").off("rowselect", adminResponsibilityTypeGridRowSelect);
            amplify.unsubscribe("SaveAction", saveAction);
            amplify.unsubscribe(AmplifyActions.Unsubscribe, unsubscribe);
        }

        //#endregion

        context
            .render(templatePath + 'governance.admin.html', pageViewModel)
            .appendTo(context.$element())
            .then(function (content) {
                context.contentHeader(pageViewModel);

                $('#SideIcons').PageTools({ type: type, id: 0 });

                GovernanceSource =
                            {
                                datatype: 'json',
                                url: '/api/ownership/types',
                                datafields:
                                [
                                    { name: 'ID' },
                                    { name: 'Name' }
                                ]
                            };

                GovernanceAdapter = new $.jqx.dataAdapter(GovernanceSource);

                var loadAfterPermissionsRetrieved = function () {

                    var tools = [];
                    if (permissions.HasPermission("Root", "Create")) {
                        tools.push({ icon: 'plus', uri: '/form/AddResponsibilityType?Group=1', context: contextList.ResponsibilityType, title: 'Add responsibility type' });
                    }
                    TileTools('#AdminResponsibilityTypeGridTools', tools);

                    $("#AdminResponsibilityTypeGrid").jqxGrid({
                        altrows: true,
                        width: grid_width,
                        pagesizeoptions: ['10', '20', '50'],
                        pagesize: 20,
                        autoheight: true,
                        sortable: true,
                        filterable: true,
                        showfilterrow: true,
                        pageable: true,
                        groupable: false,
                        source: GovernanceAdapter,
                        theme: list_theme,
                        columns: [
                            { datafield: "Name", text: "Name" },
                            {
                                text: '',
                                dataField: 'ID',
                                width: 80,
                                filterable: false,
                                cellsrenderer: function (index, datafield, value, defaultvalue, column, data) {

                                    var tools = [];

                                    if (permissions.HasPermission('Root', 'Update')) {
                                        tools.push({ icon: 'pencil', urlprefix: '/form/EditResponsibilityType?id={0}' });
                                    }

                                    if (permissions.HasPermission('Root', 'Delete')) {
                                        tools.push({ icon: 'trash-o', urlprefix: '/form/DeleteResponsibilityType?id={0}' });
                                    }

                                    return renderToolsHtml(value, tools, contextList.OwnershipType);
                                }
                            }
                        ]
                    });

                };

                permissions.GetPermissionsForObject(type, 0).then(loadAfterPermissionsRetrieved);

                //#region Event Subscriptions

                $("#AdminResponsibilityTypeGrid").one("bindingcomplete", adminResponsibilityTypeGridBindingComplete);
                $("#AdminResponsibilityTypeGrid").on("rowselect", adminResponsibilityTypeGridRowSelect);
                amplify.subscribe("SaveAction", saveAction);
                amplify.subscribe(AmplifyActions.Unsubscribe, unsubscribe);

                //#endregion
            });
    });
}
function groups_admin(app, pageViewModel, templatePath, contextList) {
    app.get('#/groups/administration', function (context) {
        context.app.swap('');
        context.title(pageViewModel.Title);

        var type = 'Group';

        pageViewModel.breadcrumbs = [];
        pageViewModel.breadcrumbs.push({ Name: 'Administration' });
        pageViewModel.breadcrumbs.push({ Name: 'Security' });
        pageViewModel.breadcrumbs.push({ Name: pageViewModel.Title, Active: true });

        var permissions = new PermissionsModel();

        var GroupsAdapter;
        var GroupsSource;

        //#region Event Handlers

        function listBindingComplete(event) {
            var rowCount = $('#List').jqxGrid('getdisplayrows').length;
            if (rowCount > 0) {
                $('#List').jqxGrid('selectrow', 0);
            }
        }

        function listRowSelect(event) {
            var data = event.args.row;

            //#region Tiles

            amplify.publish(AmplifyActions.TileUnsubscribe, {});
            GroupMembersGrid("MembersTile", contextList, permissions, data.ID);

            //#endregion

            $('#SideIcons').PageTools("reload", type, data.ID, 'root');
        }

        function refreshActionMenu(data) {
            $('#SideIcons').PageTools('refresh');
        }

        function saveAction(data) {
            try {
                switch (data.context) {
                    case contextList.Group:
                        $('#List').jqxGrid('updatebounddata');
                        break;
                }
            } catch (e) { }
        }

        function unsubscribe(data) {
            GroupsAdapter = null;
            GroupsSource = null;

            $("#List").off("bindingcomplete", listBindingComplete);
            $("#List").off("rowselect", listRowSelect);
            amplify.unsubscribe("RefreshActionMenu", refreshActionMenu);
            amplify.unsubscribe("SaveAction", saveAction);
            amplify.unsubscribe(AmplifyActions.Unsubscribe, unsubscribe);
        }

        //#endregion

        context
            .render(templatePath + 'groups.admin.html', pageViewModel)
            .appendTo(context.$element())
            .then(function (content) {
                context.contentHeader(pageViewModel);

                $('#SideIcons').PageTools({ type: type, id: 0, context: 'root' });

                var loadPermissionsDependentTiles = function () {

                    var tools = [];
                    if (permissions.HasPermission("Root", "Create")) {
                        tools.push({ icon: 'plus', uri: '/form/AddGroup', context: contextList.Group, title: 'Add group' });
                    }
                    TileTools('#ListTools', tools);

                    //#region Grid

                    GroupsSource = {
                        datatype: 'json',
                        url: '/api/groups',
                        datafields: [
                            { name: 'ID' },
                            { name: 'Name' }
                        ]
                    };

                    GroupsAdapter = new $.jqx.dataAdapter(GroupsSource);

                    $("#List").jqxGrid({
                        altrows: true,
                        width: grid_width,
                        pagesizeoptions: ['10', '20', '50'],
                        pagesize: 20,
                        autoheight: true,
                        sortable: true,
                        filterable: true,
                        showfilterrow: true,
                        pageable: true,
                        source: GroupsAdapter,
                        theme: theme,
                        columns: [
                            { datafield: "Name", text: "Name" },
                            {
                                text: '',
                                dataField: 'ID',
                                width: 120,
                                filterable: false,
                                sortable: false,
                                cellsrenderer: function (row, column, value) {
                                    var tools = [
                                        { isitemlink: true, urlprefix: '#/groups/{0}' }
                                    ];
                                    if (permissions.HasPermission("Root", "Update")) {
                                        tools.push({ icon: 'pencil', urlprefix: '/form/EditGroup?id={0}' });
                                    }
                                    if (permissions.HasPermission("Root", "Delete")) {
                                        tools.push({ icon: 'trash-o', urlprefix: '/form/DeleteGroup?id={0}' });
                                    }

                                    return renderToolsHtml(value, tools, contextList.Group);
                                }
                            }
                        ]
                    });

                    //#endregion

                    //#region Event Subscriptions

                    $("#List").on("bindingcomplete", listBindingComplete);
                    $("#List").on("rowselect", listRowSelect);
                    amplify.subscribe("RefreshActionMenu", refreshActionMenu);
                    amplify.subscribe("SaveAction", saveAction);
                    amplify.subscribe(AmplifyActions.Unsubscribe, unsubscribe);

                    //#endregion

                }

                permissions.GetPermissionsForObject(type, 0).then(loadPermissionsDependentTiles);
            });
    });
}
function groups_item(app, pageViewModel, templatePath, contextList) {
    app.get('#/groups/:id', function (context) {
        context.app.swap('');

        var id = context.params['id'];
        var type = 'Group';

        pageViewModel.breadcrumbs = [];
        pageViewModel.breadcrumbs.push({ Name: 'Groups' });
        pageViewModel.breadcrumbs.push({ Name: pageViewModel.Title, Active: true });

        var permissions = new PermissionsModel();
        var socialTile = new GroupSocialMicroTileModel(id);

        $.getJSON('/api/groups/' + id, function (json) {
            pageViewModel.Title = json.Name;
            pageViewModel.Directions = json.Description;
            pageViewModel.breadcrumbs.push({ Name: json.Name, Active: true });

            context.title(pageViewModel.Title);

            //#region Event Handlers

            function commandExecuted(commandName) {
                switch (commandName) {
                    case 'follow':
                        socialTile.GetStatistics();
                        break;
                }
            }

            function refreshActionMenu(data) {
                $('#SideIcons').PageTools("reload", type, id);
            }

            function saveAction(data) {
                try {
                    switch (data.context) {
                        case contextList.ResourceGroup:
                            socialTile.GetStatistics();
                            break;
                        case contextList.Artifact:
                            $('#SideIcons').PageTools("reload", data.custom.ObjectType, data.custom.ObjectID, "default");
                            break;
                        case contextList.Synonym:
                            $('#DetailWidget .content').load('/parts/' + data.custom.ObjectType + '/' + data.custom.ObjectID + '/detailwithsynonyms');
                            $('#SideIcons').PageTools("reload", data.custom.ObjectType, data.custom.ObjectID, "default");
                            break;
                    }
                } catch (e) {
                    logError("artifact.item : SaveAction", e);
                }
            }

            function unsubscribe(data) {
                amplify.unsubscribe("CommandExecuted", commandExecuted);
                amplify.unsubscribe("RefreshActionMenu", refreshActionMenu);
                amplify.unsubscribe("SaveAction", saveAction);
                amplify.unsubscribe(AmplifyActions.Unsubscribe, unsubscribe);
            }

            //#endregion

            context
                .render(templatePath + 'groups.item.html', pageViewModel)
                .appendTo(context.$element())
                .then(function (content) {
                    context.contentHeader(pageViewModel);

                    $('#SideIcons').PageTools({ type: type, id: id });

                    permissions.GetPermissionsForObject(type, id);

                    $('#OwnedTile').load('/parts/groups/' + id + '/ownership');
                    GroupMembersGrid("MembersTile", contextList, permissions, id);

                    var GroupSocial = new BoardViewModel();
                    ko.applyBindings(GroupSocial, document.getElementById('GroupBoard'));
                    GroupSocial.changeObject(type, id);

                    
                    ko.applyBindings(socialTile, document.getElementById('SocialTile'));
                    socialTile.GetStatistics();

                    $("#RandomQuestion").RandomSurveyQuestion({ objectType: type, objectID: id });

                    amplify.subscribe("CommandExecuted", commandExecuted);
                    amplify.subscribe("RefreshActionMenu", refreshActionMenu);
                    amplify.subscribe("SaveAction", saveAction);
                    amplify.subscribe(AmplifyActions.Unsubscribe, unsubscribe);
                });
        });
    });
}
